/** The live connection wrapper owns source handles through capture, even when its public result is closed. */
@Timeout(30)
class LmdbProjectedCaptureLifetimeTest {

	@Test
	void resultCloseDefersNativeSourceRetirementUntilCurrentRowCaptureCompletes(@TempDir Path directory)
			throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setInlineLiterals(false);
		var seed = new SailRepository(new LmdbStore(directory.toFile(), config));
		var vf = SimpleValueFactory.getInstance();
		try (var connection = seed.getConnection()) {
			for (int i = 0; i < 8; i++) {
				connection.add(vf.createIRI("urn:capture:s:" + i), vf.createIRI("urn:capture:p"),
						vf.createLiteral("uninitialized payload " + i));
			}
		} finally {
			seed.shutDown();
		}
		var store = new ObservedStore(directory.toFile(), config);
		store.init();
		try (var workers = Executors.newVirtualThreadPerTaskExecutor(); var connection = store.getConnection()) {
			var query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
					"SELECT ?s ?value WHERE { ?s <urn:capture:p> ?value }", null);
			try (var rows = connection.evaluate(query.getTupleExpr(), null, EmptyBindingSet.getInstance(), false)) {
				store.values.armed = true;
				var reading = workers.submit(rows::next);
				try {
					assertTrue(store.values.captureEntered.await(10, TimeUnit.SECONDS),
							"the actual native projection must enter dictionary-handle capture");
					rows.close();
					store.values.capturedSnapshot.ensureValid();
					assertFalse(reading.isDone(), "the admitted call must still own its paused capture");
				} finally {
					store.values.releaseCapture.countDown();
				}
				var row = reading.get(10, TimeUnit.SECONDS);
				assertInstanceOf(NativeProjectedBindingSet.class, row);
				assertEquals(2, store.values.captures.get(), "closing cannot pull another row speculatively");
				for (var binding : row) {
					assertInstanceOf(ValueStoreRevision.Lazy.class,
							((LmdbValue) binding.getValue()).getValueStoreRevision());
				}
				assertFalse(rows.hasNext());
				connection.close();
				assertTrue(row.getValue("s").stringValue().startsWith("urn:capture:s:"));
				assertTrue(row.getValue("value").stringValue().startsWith("uninitialized payload "));
				assertEquals(2, store.values.captures.get(), "detached values cannot call the retired source");
			}
		} finally {
			store.values.releaseCapture.countDown();
			store.shutDown();
		}
	}

	private static final class ObservedStore extends LmdbStore {
		private CapturingValueStore values;

		private ObservedStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketches,
					(valueDirectory, valueProperties, valueConfig) -> values = new CapturingValueStore(valueDirectory,
							valueProperties, valueConfig),
					TripleStore::new);
		}
	}

	private static final class CapturingValueStore extends ValueStore {
		private final CountDownLatch captureEntered = new CountDownLatch(1);
		private final CountDownLatch releaseCapture = new CountDownLatch(1);
		private final AtomicInteger captures = new AtomicInteger();
		private volatile ReadSnapshot capturedSnapshot;
		private volatile boolean armed;

		private CapturingValueStore(File directory, StoreProperties properties, LmdbStoreConfig config)
				throws IOException {
			super(directory, properties, config);
		}

		@Override
		LmdbValue getLazyValue(ReadSnapshot snapshot, long id, int positionMask) throws IOException {
			if (armed && captures.incrementAndGet() == 1) {
				capturedSnapshot = snapshot;
				captureEntered.countDown();
				try {
					if (!releaseCapture.await(10, TimeUnit.SECONDS)) {
						throw new IOException("Timed out waiting for concurrent result close");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new IOException(interrupted);
				}
			}
			return super.getLazyValue(snapshot, id, positionMask);
		}
	}
}
